    pub fn is_abstract(self) -> bool {
        matches!(self,
             ElementKind::ConnectorAsUsage
            | ElementKind::ControlNode
            | ElementKind::Element
            | ElementKind::Expose
            | ElementKind::Import
            | ElementKind::InstantiationExpression
            | ElementKind::LoopActionUsage
            | ElementKind::Relationship
        )
    }

